          "type": "number"
        }
      },
      "type": "object"
    },
    "shape": {
      "description": "The shape type (e.g. circle, rectangle, triangle)",
      "type": "string"
    }
  },
  "required": [
    "shape",
    "dimensions"
  ],
  "type": "object"
}
```

