        "dbs_pass": {
          "type": "string",
          "minLength": 0
        },
        "dbs_unicode": {
          "type": "boolean"
        },
        "dbs_charset": {
          "type": "string",
          "enum": [
            "utf8",
            "utf16"
          ]
        }
      },
      "required": [
        "dbs_addr",
        "dbs_port",
        "dbs_login",
        "dbs_pass",
        "dbs_unicode",
        "dbs_charset"
      ]
    }
  },
  "type": "object",
  "properties": {
    "ntm-config": {
      "type": "object",
      "properties": {
        "crawlers": {
          "$ref": "#/definitions/crawlers"
        },
        "db": {
          "$ref": "#/definitions/db"
        },
        "dbs": {
          "$ref": "#/definitions/dbs"
        }
      },
      "required": [
        "crawlers",
        "db",
        "dbs"
      ]
    }
  }
}

