  "_meta": {
    "hostvars": {
      "host1": {
        "var1": "value1",
        "var2": "value2"
      },
      "host2": {
        "var1": "value3",
        "var2": "value4"
      }
    }
  },
  "groups": {
    "group1": {
      "hosts": [
        "host1",
