        {
          "properties": {
            "type": {
              "enum": [
                "value1"
              ]
            }
          },
          "required": [
            "dataSets"
          ]
        },
        {
          "properties": {
            "type": {
              "enum": [
                "value2"
              ]
            }
          },
          "required": [
            "subFields"
          ]
        }
      ],
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "value2",
            "value1"
          ]
        },
        "dataSets": {
          "type": "array",
          "items": {
            "type": "object",
            "required": [
              "code",
              "subFields"
            ],
            "properties": {
              "code": {
