  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "$schema": {
      "type": "string"
    },
    "$tool": {
      "const": "svg-patterns",
      "description": "Must be set to svg-patterns.",
      "type": "string"
    },
    "dist": {
      "description": "The output file path (relative to the pwd), support .ts .js .json.",
